"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["26034"],{73234(e){e.exports=JSON.parse('{"id":"V4-062","slug":"annual-general-meeting","term":"Annual General Meeting","also_known_as":[],"difficulty":"Beginner","definition":"An annual general meeting (AGM) is a yearly meeting of a company\u2019s shareholders, at which they receive information about the company\u2019s performance and vote on important matters, such as electing directors and approving the accounts.","explanation":["Most countries require public companies to hold an AGM each year. Typical business includes presenting the annual report and accounts, electing or re-electing directors, appointing the auditor, approving dividends and executive pay and voting on any shareholder proposals.","The AGM gives shareholders an opportunity to question the board and management directly. Shareholders who cannot attend can usually vote by proxy, appointing someone else to vote for them or submitting voting instructions in advance.","For example, at a company\u2019s AGM, shareholders might vote to re-elect the board, approve a dividend and reject a proposed increase in executive pay.","Many AGMs are now held in hybrid form, with shareholders able to attend in person or online, and some are held entirely online, a practice that expanded during the COVID-19 pandemic. Companies may also call extraordinary general meetings during the year to approve urgent matters, such as a major acquisition. In the United States, the AGM is often called the annual meeting of shareholders."],"note":"","total":1725,"prev":{"slug":"angel-investor","term":"Angel Investor"},"next":{"slug":"annual-percentage-rate","term":"Annual Percentage Rate (APR)"}}')}}]);